import pytest
from merge import merge_layers
from settings import build_config


def test_nested_merge_and_independent_tree():
    first = {'network': {'timeout': 3, 'hosts': ['a']}}
    result = merge_layers(first, {'network': {'timeout': 5}})
    assert result == {'network': {'timeout': 5, 'hosts': ['a']}}
    result['network']['hosts'].append('b')
    assert first['network']['hosts'] == ['a']


def test_environment_is_last_layer():
    assert build_config({'network': {'timeout': 2}}, {},
                        {'APP_TIMEOUT': ' +12 ', 'APP_DEBUG': 'FALSE'}) == {
                            'network': {'timeout': 12}, 'debug': False}


@pytest.mark.parametrize('value', ['0', '-2', '1.2', 'no'])
def test_bad_timeout(value):
    with pytest.raises(ValueError):
        build_config({}, {}, {'APP_TIMEOUT': value})

def _clone(value):
    """Return a deep copy of dictionaries/lists; other values are atomic."""
    if isinstance(value, dict):
        return {key: _clone(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_clone(item) for item in value]
    return value


def _merge(base, override):
    result = {key: _clone(value) for key, value in base.items()}
    for key, value in override.items():
        current = result.get(key)
        if isinstance(current, dict) and isinstance(value, dict):
            result[key] = _merge(current, value)
        else:
            result[key] = _clone(value)
    return result


def merge_layers(*layers):
    """Merge dictionary layers from left to right.

    Later values win. Nested dictionaries are merged recursively; lists and
    every other value (including ``None``) replace the earlier value. The
    result is an independent tree that shares no mutable containers with the
    inputs, and the inputs are never modified.
    """
    result = {}
    for layer in layers:
        if not isinstance(layer, dict):
            raise TypeError("every layer must be a dictionary")
        result = _merge(result, layer)
    return result
